package net.civeira.phylax.feature.identity.userpurposeconsent.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.userpurposeconsent.domain.UserPurposeConsent;
import net.civeira.phylax.feature.identity.userpurposeconsent.domain.valueobject.UserAgentVO;

class UserAgentValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of user agent of user purpose consent")
  void test_user_agent_value_holder_assign_plain_value() {
    Object holder = new Object();
    UserAgentValueHolder<Object> value = new UserAgentValueHolder<>(holder);
    Assertions.assertSame(holder, value.userAgent("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getUserAgentValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getUserAgent().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.userAgentNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getUserAgentValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getUserAgent().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of user agent of user purpose consent")
  void test_user_agent_value_holder_assign_value_object() {
    Object holder = new Object();
    UserAgentValueHolder<Object> value = new UserAgentValueHolder<>(holder);
    UserAgentVO vo = UserAgentVO.from("one");
    Assertions.assertFalse(value.getUserAgentValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.userAgent(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getUserAgentValue().orElseThrow());
    Assertions.assertSame(holder, value.userAgent(Optional.empty()));
    Assertions.assertFalse(value.getUserAgentValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.userAgent(Optional.of(vo)));
    Assertions.assertSame(vo, value.getUserAgentValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of user agent of user purpose consent against the original")
  void test_user_agent_value_holder_read() {
    Object holder = new Object();
    UserAgentValueHolder<Object> value = new UserAgentValueHolder<>(holder);
    UserAgentVO vo = UserAgentVO.from("one");
    UserAgentVO other = UserAgentVO.from("one");
    UserPurposeConsent original = Mockito.mock(UserPurposeConsent.class);
    Mockito.when(original.getUserAgentValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readUserAgent(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readUserAgent(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.userAgent(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readUserAgent(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readUserAgent(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of user agent of user purpose consent")
  void test_user_agent_value_holder_unset() {
    Object holder = new Object();
    UserAgentValueHolder<Object> value = new UserAgentValueHolder<>(holder);
    UserAgentVO vo = UserAgentVO.from("one");
    value.userAgent(vo);
    Assertions.assertSame(holder, value.unsetUserAgentIfMatches("userAgent_other"));
    Assertions.assertTrue(value.getUserAgentValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetUserAgentIfMatches("userAgent"));
    Assertions.assertFalse(value.getUserAgentValue().isPresent(),
        "The field name must clear the value");
    value.userAgent(vo);
    Assertions.assertSame(holder, value.unsetUserAgent());
    Assertions.assertFalse(value.getUserAgentValue().isPresent(), "Unset must clear the value");
  }
}
